#include "hft/market/orderbook.hpp"
namespace hft{double top_imbalance(const Book10&b)noexcept{double d=b.bids[0].quantity+b.asks[0].quantity;return d?(b.bids[0].quantity-b.asks[0].quantity)/d:0;}double depth_imbalance(const Book10&b)noexcept{double x=0,y=0;for(int i=0;i<10;i++){x+=b.bids[i].quantity;y+=b.asks[i].quantity;}double d=x+y;return d?(x-y)/d:0;}double microprice(const Book10&b)noexcept{double x=b.bids[0].quantity,y=b.asks[0].quantity,d=x+y;return d?(b.asks[0].price*x+b.bids[0].price*y)/d:(b.bids[0].price+b.asks[0].price)/2;}double depth_slope(const Book10&b)noexcept{double s=0;for(int i=1;i<10;i++)s+=(b.bids[i].quantity-b.asks[i].quantity)/(1+b.bids[0].price-b.bids[i].price+b.asks[i].price-b.asks[0].price);return s/9;}MicroFeatures compute_micro_features(const Book10&b){auto t=top_imbalance(b),d=depth_imbalance(b);return{t,d,microprice(b),b.asks[0].price-b.bids[0].price,.65*t+.35*d,depth_slope(b)};}}
